<script setup lang="ts">
const props=defineProps<{csrf:string,activityId:number,annotation:any,laps:any[]}>(),emit=defineEmits(['saved'])
const form=ref<any>({intent:'',equipment:'',structure:'',notes:'',sets:[],...props.annotation})
const preview=ref<any>(null),message=ref(''),busy=ref(false)
watch(()=>props.activityId,()=>{form.value={intent:'',equipment:'',structure:'',notes:'',sets:[],...props.annotation};preview.value=null})
watch(form,()=>{preview.value=null},{deep:true})
async function save(confirm=false){busy.value=true;message.value='';try{
 const r=await $fetch<any>('/api/platform/memory',{method:'POST',headers:{'x-csrf-token':props.csrf},body:confirm?{kind:'session-annotations',confirm:true,preview_token:preview.value.preview_token}:{...form.value,kind:'session-annotations',activity_id:props.activityId}})
 if(confirm){message.value='Contesto e serie dichiarate salvati.';preview.value=null;emit('saved')}else preview.value=r
}catch(e:any){message.value=e.data?.error||'Modifica non salvata'}finally{busy.value=false}}
</script>
<template><details class="panel"><summary class="font-semibold text-green-400 cursor-pointer">Correggi la struttura e aggiungi il contesto della seduta</summary><p class="muted mt-4">Le dichiarazioni restano separate dal FIT originale. Seleziona gli indici dei lap registrati; i gruppi non possono sovrapporsi. Le metriche vengono ricalcolate dal backend sui lap scelti.</p><div class="grid sm:grid-cols-2 gap-3 mt-4"><label class="text-xs">Intenzione del lavoro<select v-model="form.intent" class="block w-full mt-1" aria-label="Intenzione seduta"><option value="">Non dichiarata</option><option value="aerobico">Aerobico</option><option value="soglia">Soglia</option><option value="tecnica">Tecnica</option><option value="gara">Gara</option><option value="altro">Altro</option></select></label><label class="text-xs">Attrezzi e contesto<input v-model="form.equipment" class="block w-full mt-1" aria-label="Attrezzi seduta"/></label></div><textarea v-model="form.structure" class="w-full mt-4" rows="2" aria-label="Struttura dichiarata" placeholder="Es. riscaldamento, 10 × 100 con recupero, defaticamento"/><div v-for="(g,i) in form.sets" class="flex flex-wrap gap-2 items-end mt-3"><label class="text-xs">Nome<input v-model="g.label" class="block w-full mt-1"/></label><label class="text-xs">Primo lap<select v-model.number="g.first_lap" class="block mt-1"><option v-for="l in laps" :value="l.lap_index">{{l.lap_index}}</option></select></label><label class="text-xs">Ultimo lap<select v-model.number="g.last_lap" class="block mt-1"><option v-for="l in laps" :value="l.lap_index">{{l.lap_index}}</option></select></label><UButton color="neutral" variant="outline" @click="form.sets.splice(i,1)">Rimuovi gruppo</UButton></div><UButton class="mt-3" variant="outline" v-if="laps.length" @click="form.sets.push({label:'Serie dichiarata',first_lap:laps[0].lap_index,last_lap:laps[0].lap_index})">Aggiungi gruppo di lap</UButton><textarea v-model="form.notes" rows="2" class="block w-full mt-4" aria-label="Note seduta" placeholder="Sensazioni e intenzioni che l’orologio non può misurare"/><UButton class="mt-4" @click="save()" :loading="busy">Anteprima struttura e contesto</UButton><div v-if="preview" class="rounded-xl border border-green-800 p-4 mt-4"><h3 class="font-semibold">Anteprima da confermare</h3><p class="muted mt-3">{{preview.preview.intent||'Intenzione non dichiarata'}} · {{preview.preview.equipment}}</p><p class="muted mt-2">{{preview.preview.structure}}</p><p v-for="g in preview.preview.sets" class="text-sm mt-2">{{g.label}} · lap {{g.first_lap}}–{{g.last_lap}}</p><UButton class="mt-4" @click="save(true)" :loading="busy">Conferma struttura e contesto</UButton></div><p role="status" class="text-sm text-amber-300 mt-3">{{message}}</p></details></template>
